"""monitor.py — generated by obligations/boundary/generate.py from kernel tags ['D', 'F', 'INV1', 'P0', 'P1', 'P2', "P2'", 'P3', 'R1', 'R2']. Do not edit.

CONTRACT (what a silent monitor establishes, over the emitted events only):
  keys       a request is (account_id, request_id); ids may repeat across accounts
  P0/P1-obs  every auth.decided has decision == (amount <= available_at_decision ? AUTHORIZED : DECLINED)
  AVAIL      available_at_decision equals limit - posted - live holds reconstructed from the stream
  P2-obs     reservation.created only for a request whose decision in this account is AUTHORIZED, with the SAME
             amount, only once, never while a hold is live, never after the request was released (R1 terminal)
  OPERATION  events carry op_id; an operation's events are contiguous and end with exactly one op.committed whose
             composition matches its op: create_account=[account.created]; authorize=[auth.decided (+reservation.created
             iff AUTHORIZED)]; release=[reservation.released]. Duplicate commits, commits for unknown ops, events after a
             commit, interleaved ops and open ops at the end are alerts
  COMPLETENESS a valid stream is complete only relative to a watermark: run(events, expected_last_seq=N) alerts if the
             stream ends before N; without a watermark the monitor cannot know that later operations were omitted
  P3-obs     at most one auth.decided per (account, request)
  INV1-obs   reconstructed posted + holds <= limit at all times
  PRODUCER   every event carries producer == "auth-service";  ORDER: seq strictly increasing when present
  CHAIN      hash == sha256(canonical(event without hash)) and prev_hash == previous event's hash (detects alteration;
             does not authenticate a source that rewrites the whole chain)
  STATE      op.committed.state_after equals the state reconstructed from the stream (limit, posted, reserved)
Negative suite: obligations/boundary/test_monitor.py. A silent monitor says nothing about events never emitted.
"""
from collections import defaultdict
import hashlib, json

PRODUCER = "auth-service"
ZERO = "0" * 64
def canonical(obj): return json.dumps(obj, sort_keys=True, separators=(",", ":"))


class Monitor:
    def __init__(self):
        self.limit = {}; self.posted = defaultdict(int); self.holds = defaultdict(dict)
        self.decided = {}; self.released = set()
        self.open = None; self.closed_ops = set()                         # operation lifecycle (by op_id)
        self.alerts = []; self.antecedents = defaultdict(int); self.last_seq = None; self.last_hash = ZERO

    def alert(self, code, ev, **info):
        self.alerts.append({"code": code, "seq": ev.get("seq"), "account_id": ev.get("account_id"),
                            "request_id": ev.get("request_id"), **info})

    def on_event(self, ev):
        t = ev.get("type"); acct = ev.get("account_id"); key = (acct, ev.get("request_id"))
        if ev.get("producer") != PRODUCER:
            self.alert("PRODUCER", ev, producer=ev.get("producer"))
        if ev.get("seq") is not None:
            if self.last_seq is not None and ev["seq"] <= self.last_seq:
                self.alert("ORDER", ev)
            self.last_seq = ev["seq"]
        body = {k: v for k, v in ev.items() if k not in ("hash", "seq")}
        if ev.get("prev_hash") != self.last_hash or ev.get("hash") != hashlib.sha256(canonical(body).encode()).hexdigest():
            self.alert("CHAIN", ev)
        self.last_hash = ev.get("hash", self.last_hash)
        # ---- operation lifecycle
        op_id = ev.get("op_id")
        if op_id is None:
            self.alert("OP-missing-id", ev)
        elif op_id in self.closed_ops:
            self.alert("OP-after-commit", ev, note="event or second commit for an already committed operation"); return
        elif self.open is None:
            self.open = {"id": op_id, "types": [], "acct": acct, "rid": ev.get("request_id")}
        elif self.open["id"] != op_id:
            self.alert("OP-interleaved", ev, open=self.open["id"]); self.open = {"id": op_id, "types": [], "acct": acct, "rid": ev.get("request_id")}
        if self.open and t != "op.committed":
            self.open["types"].append(t)
        if t == "account.created":
            if acct in self.limit:
                self.alert("DUP-ACCOUNT", ev)
            self.limit[acct] = ev["limit"]
        elif t == "auth.decided":
            if acct not in self.limit:
                self.alert("UNKNOWN-ACCOUNT", ev)
            if key in self.decided:
                self.alert("P3-obs", ev, note="second decision for a request"); return
            self.decided[key] = (ev["decision"], ev["amount"])
            recon = self.limit.get(acct, 0) - self.posted[acct] - sum(self.holds[acct].values())
            if recon != ev["available_at_decision"]:
                self.alert("AVAIL-MISMATCH", ev, emitted=ev["available_at_decision"], reconstructed=recon)
            if ev["amount"] > ev["available_at_decision"]:
                self.antecedents["P1"] += 1
                if ev["decision"] != "DECLINED":
                    self.alert("P1-obs", ev)
            else:
                self.antecedents["P0"] += 1
                if ev["decision"] != "AUTHORIZED":
                    self.alert("P0-obs", ev)
        elif t == "reservation.created":
            dec = self.decided.get(key)
            if dec is None or dec[0] != "AUTHORIZED":
                self.alert("P2-obs", ev, decision=dec and dec[0]); return
            if dec[1] != ev["amount"]:
                self.alert("P2-amount", ev, decided=dec[1], reserved=ev["amount"])
            if key in self.released:
                self.alert("R1-terminal", ev)
            if ev["request_id"] in self.holds[acct]:
                self.alert("P2-duplicate-hold", ev)
            self.holds[acct][ev["request_id"]] = ev["amount"]
            if self.posted[acct] + sum(self.holds[acct].values()) > self.limit.get(acct, 0):
                self.alert("INV1-obs", ev)
        elif t == "reservation.released":
            if ev["request_id"] not in self.holds[acct]:
                self.alert("R1-unknown", ev)
            self.holds[acct].pop(ev["request_id"], None); self.released.add(key)
        elif t == "op.committed":
            op = ev.get("op"); st = ev.get("state_after") or {}
            recon = {"limit": self.limit.get(acct), "posted": self.posted[acct], "reserved": sum(self.holds[acct].values())}
            if {k: st.get(k) for k in recon} != recon:
                self.alert("STATE", ev, declared=st, reconstructed=recon)
            cur = self.open or {"types": [], "id": op_id}
            types = cur["types"]
            expected = {"create_account": [["account.created"]],
                        "authorize": [["auth.decided"], ["auth.decided", "reservation.created"]],
                        "release": [["reservation.released"]]}.get(op)
            if expected is None:
                self.alert("OP-unknown-kind", ev, op=op)
            elif types not in expected:
                self.alert("OP-composition", ev, op=op, got=types)
            elif op == "authorize":
                dec = self.decided.get(key)
                want = ["auth.decided", "reservation.created"] if dec and dec[0] == "AUTHORIZED" else ["auth.decided"]
                if types != want: self.alert("COMPLETE-" + ("missing-reservation" if len(types) < len(want) else "reservation-on-decline"), ev)
            self.closed_ops.add(cur["id"]); self.open = None
        else:
            self.alert("UNKNOWN-EVENT", ev, type=t)

    def run(self, events, expected_last_seq=None):
        for ev in events:
            self.on_event(ev)
        if self.open is not None:                             # an operation that never committed
            self.alert("COMPLETE-unterminated", {"account_id": self.open.get("acct"), "request_id": self.open.get("rid")}, op=self.open["id"])
        if expected_last_seq is not None and (self.last_seq or 0) < expected_last_seq:
            self.alert("INCOMPLETE", {"account_id": None, "request_id": None}, last_seq=self.last_seq, expected=expected_last_seq)
        return {"alerts": self.alerts, "antecedents": dict(self.antecedents), "events": len(events)}
